sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var method = request.httpMethod;
    try {
        if (method !== 'POST') {
            response.setStatus(405);
            return { success: false, error: 'Method not allowed' };
        }
        var data = request.body.data;
        if (!data || !data.text) {
            response.setStatus(400);
            return { success: false, error: 'text is required' };
        }
        var result = suggest(data.text);
        response.setStatus(200);
        return { success: true, result: result };
    } catch (e) {
        response.setStatus(500);
        return { success: false, error: e.message };
    }

    function suggest(text) {
        var lower = text.toLowerCase();
        var complaint_type = 'general';
        var urgency = 'low';
        var typeKeywords = {
            'damaged': 'damaged_item', 'missing': 'missing_item', 'late': 'delivery_delay',
            'delay': 'delivery_delay', 'wrong': 'wrong_item', 'rude': 'partner_behavior',
            'spoiled': 'quality_issue', 'refund': 'refund_request'
        };
        for (var kw in typeKeywords) {
            if (lower.indexOf(kw) !== -1) { complaint_type = typeKeywords[kw]; break; }
        }
        var urgentKeywords = ['urgent', 'immediately', 'safety', 'injury', 'never arrived', 'fraud'];
        for (var i = 0; i < urgentKeywords.length; i++) {
            if (lower.indexOf(urgentKeywords[i]) !== -1) { urgency = 'high'; break; }
        }
        return {
            suggested_complaint_type: complaint_type,
            suggested_urgency: urgency,
            note: 'keyword stub - replace with Complaint Triage Assistant skill call'
        };
    }
})(request, response);
